export type ParsedAutoDeleverageInstruction<
  TProgram extends string = typeof LVRT_ENGINE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    adlOperator: TAccountMetas[0];
    config: TAccountMetas[1];
    bucketRisk: TAccountMetas[2];
    bucketState: TAccountMetas[3];
    fund: TAccountMetas[4];
    market: TAccountMetas[5];
    fundingState: TAccountMetas[6];
    priceState: TAccountMetas[7];
    shard: TAccountMetas[8];
    position: TAccountMetas[9];
    margin: TAccountMetas[10];
    owner: TAccountMetas[11];
  };
  data: AutoDeleverageInstructionData;
};

export function parseAutoDeleverageInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedAutoDeleverageInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      adlOperator: getNextAccount(),
      config: getNextAccount(),
      bucketRisk: getNextAccount(),
      bucketState: getNextAccount(),
      fund: getNextAccount(),
      market: getNextAccount(),
      fundingState: getNextAccount(),
      priceState: getNextAccount(),
      shard: getNextAccount(),
      position: getNextAccount(),
      margin: getNextAccount(),
      owner: getNextAccount(),
    },
    data: getAutoDeleverageInstructionDataDecoder().decode(instruction.data),
  };
}
